using UnityEngine;using System;using System.Collections.Generic;using System.IO;
public static class ValidateTrikeBoxes {public static string Main(){GameObject floor=null,copy=null,handler=null;var boxes=new List<GameObject>();int checks=0;void Check(bool v,string m){if(!v)throw new Exception(m);checks++;}try{floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(10000,-.5f,10000);floor.transform.localScale=new Vector3(30,1,30);copy=UnityEngine.Object.Instantiate(UnityEngine.Object.FindFirstObjectByType<TrikeController>().gameObject,new Vector3(10000,.02f,10000),Quaternion.identity);var rig=copy.GetComponent<BicycleController>();handler=new GameObject("Cargo handler fixture");var rider=handler.AddComponent<PlayerBicycleInteraction>();rider.bicycle=rig;for(int i=0;i<4;i++){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);boxes.Add(go);go.transform.localScale=Vector3.one*.3f;go.AddComponent<Rigidbody>();var box=go.AddComponent<BicycleCargoBox>();Check(box.Load(rig.FreeCargoSlot()),"Load bed slot "+i);}Check(rig.FreeCargoSlot()==null,"All four slots filled");Physics.SyncTransforms();Check(rider.TryUnloadBox(boxes[0].GetComponent<BicycleCargoBox>()),"Unload beside wide cab");Check(rig.FreeCargoSlot()!=null,"Unloaded bed slot free");string result="PASS: "+checks+" four-slot box capacity and wide-body unloading checks.";File.WriteAllText("output/Trike/box-validation.txt",result);return result;}finally{foreach(var b in boxes)if(b)UnityEngine.Object.DestroyImmediate(b);if(handler)UnityEngine.Object.DestroyImmediate(handler);if(copy)UnityEngine.Object.DestroyImmediate(copy);if(floor)UnityEngine.Object.DestroyImmediate(floor);}}}
